WITH filtered AS (SELECT *, UPPER(plan) AS plan_upper FROM subscriptions WHERE start_date BETWEEN '2023-06-22' AND '2024-12-01') SELECT id, customer_id, plan, start_date, end_date, RANK() OVER (PARTITION BY plan ORDER BY monthly_fee) AS monthly_fee_rank, RANK() OVER (PARTITION BY status ORDER BY monthly_fee DESC NULLS FIRST) AS monthly_fee_rank_2, NTILE(4) OVER (ORDER BY monthly_fee DESC, id) AS monthly_fee_bucket FROM filtered;
